INSERT INTO public.interview_question_definitions(question_key,version,definition) VALUES
 ('A1',1,'{"key": "A1", "text": "Your full name, current grade, and the year you expect to graduate high school.", "stage": 1, "section": "A"}'::jsonb),
 ('A2',1,'{"key": "A2", "text": "Your high school''s name and location. Is it public, private, charter, magnet, homeschool, or something else?", "stage": 1, "section": "A"}'::jsonb),
 ('A3',1,'{"key": "A3", "text": "What you think you might want to study in college — or “undecided,” which is completely fine.", "stage": 1, "section": "A"}'::jsonb),
 ('A4',1,'{"key": "A4", "text": "Any colleges already on your radar, and what drew you to them (even if it''s just a name you''ve heard).", "stage": 1, "section": "A"}'::jsonb),
 ('A5',1,'{"key": "A5", "text": "Do you already have a sense of what you''d like your application to say about you? (Totally fine to leave this blank for now.)", "stage": 3, "section": "A"}'::jsonb),
 ('B1',1,'{"key": "B1", "text": "What classes are you taking this year? List any honors, AP, IB, or dual-enrollment courses you''ve taken across high school.", "stage": 2, "section": "B"}'::jsonb),
 ('B2',1,'{"key": "B2", "text": "Your GPA (weighted and/or unweighted, if you know them), and your class rank if your school uses one.", "stage": 2, "section": "B"}'::jsonb),
 ('B3',1,'{"key": "B3", "text": "Any test scores you have so far — SAT, ACT, PSAT, AP exams, or language / other proficiency tests.", "stage": 2, "section": "B"}'::jsonb),
 ('B4',1,'{"key": "B4", "text": "Your strongest subject and your weakest — and why you think that is.", "stage": 2, "section": "B"}'::jsonb),
 ('B5',1,'{"key": "B5", "text": "The class you''ve enjoyed most in your life, and what specifically made it click for you.", "stage": 2, "section": "B"}'::jsonb),
 ('B6',1,'{"key": "B6", "text": "A subject, skill, or idea you''d keep learning about even if it were never graded or tested.", "stage": 2, "section": "B"}'::jsonb),
 ('B7',1,'{"key": "B7", "text": "Anything in your record — a rough semester, a school change, an upward trend — that you''d want someone to understand the story behind.", "stage": 2, "section": "B"}'::jsonb),
 ('C1',1,'{"key": "C1", "text": "What do you find yourself reading, watching, or falling down internet rabbit holes about, just for yourself?", "stage": 2, "section": "C"}'::jsonb),
 ('C2',1,'{"key": "C2", "text": "A topic you could talk about for an hour with zero preparation.", "stage": 2, "section": "C"}'::jsonb),
 ('C3',1,'{"key": "C3", "text": "A question you don''t have the answer to but keep thinking about.", "stage": 2, "section": "C"}'::jsonb),
 ('C4',1,'{"key": "C4", "text": "The last time you really changed your mind about something that mattered to you — what moved you?", "stage": 2, "section": "C"}'::jsonb),
 ('C5',1,'{"key": "C5", "text": "Something you believe that most people around you don''t.", "stage": 2, "section": "C"}'::jsonb),
 ('C6',1,'{"key": "C6", "text": "When you get to choose what to learn, how do you go about it? Do you dive deep on one thing, sample widely, build something, argue about it?", "stage": 2, "section": "C"}'::jsonb),
 ('D1',1,'{"key": "D1", "text": "List your activities — clubs, sports, arts, volunteering, research, hobbies — ranked by how much they actually matter to you, not by how impressive they sound. For each, jot down roughly how many hours a week and weeks a year, how long you''ve done it, and any role you''ve held.", "stage": 2, "section": "D"}'::jsonb),
 ('D2',1,'{"key": "D2", "text": "Any leadership you''ve taken on — official (a title or elected role) or unofficial (the person everyone comes to, the one who makes things happen).", "stage": 2, "section": "D"}'::jsonb),
 ('D3',1,'{"key": "D3", "text": "Any jobs, internships, or paid work — including anything for a family business.", "stage": 2, "section": "D"}'::jsonb),
 ('D4',1,'{"key": "D4", "text": "Responsibilities you carry at home that wouldn''t show up on a résumé — caring for family, translating, running a household, contributing income, looking after siblings.", "stage": 2, "section": "D"}'::jsonb),
 ('D5',1,'{"key": "D5", "text": "Something you do regularly that isn''t part of any club, team, or program — a personal project, a craft, a creative habit.", "stage": 2, "section": "D"}'::jsonb),
 ('E1',1,'{"key": "E1", "text": "Who''s in your household, and where do you fall among any siblings?", "stage": 2, "section": "E"}'::jsonb),
 ('E2',1,'{"key": "E2", "text": "What languages are spoken at home?", "stage": 2, "section": "E"}'::jsonb),
 ('E3',1,'{"key": "E3", "text": "Any cultural, religious, ethnic, or community identities that matter to you — and how big a part of daily life they are.", "stage": 2, "section": "E"}'::jsonb),
 ('E4',1,'{"key": "E4", "text": "Will you be the first in your family to attend college in the U.S.? What do your parents or guardians do, and what''s their educational background?", "stage": 2, "section": "E"}'::jsonb),
 ('E5',1,'{"key": "E5", "text": "How would you describe the community you come from — your neighborhood, town, or school?", "stage": 2, "section": "E"}'::jsonb),
 ('E6',1,'{"key": "E6", "text": "Is there anything about your life or circumstances that a college would never guess just from your grades and activities?", "stage": 2, "section": "E"}'::jsonb),
 ('F1',1,'{"key": "F1", "text": "A real challenge, obstacle, or hardship you''ve faced — and how you responded to it.", "stage": 2, "section": "F"}'::jsonb),
 ('F2',1,'{"key": "F2", "text": "A genuine failure or setback, and what happened afterward.", "stage": 2, "section": "F"}'::jsonb),
 ('F3',1,'{"key": "F3", "text": "A moment when something shifted for you — in how you saw yourself, someone else, or the world.", "stage": 2, "section": "F"}'::jsonb),
 ('F4',1,'{"key": "F4", "text": "A time you had to stand up for yourself or someone else, or ask for something you needed.", "stage": 2, "section": "F"}'::jsonb),
 ('F5',1,'{"key": "F5", "text": "Something that used to be hard or scary for you that you now handle easily — what changed?", "stage": 2, "section": "F"}'::jsonb),
 ('G1',1,'{"key": "G1", "text": "Three words a close friend would honestly use to describe you.", "stage": 2, "section": "G"}'::jsonb),
 ('G2',1,'{"key": "G2", "text": "Three words a teacher would use.", "stage": 2, "section": "G"}'::jsonb),
 ('G3',1,'{"key": "G3", "text": "Something you''re proud of that would never show up on a transcript or activities list.", "stage": 2, "section": "G"}'::jsonb),
 ('G4',1,'{"key": "G4", "text": "A contradiction in yourself — a way you''re two things at once.", "stage": 2, "section": "G"}'::jsonb),
 ('G5',1,'{"key": "G5", "text": "What are you like when nobody''s assigning you anything and no one''s watching? How do you spend genuinely free time?", "stage": 2, "section": "G"}'::jsonb),
 ('G6',1,'{"key": "G6", "text": "How do you handle risk, boredom, and being wrong?", "stage": 2, "section": "G"}'::jsonb),
 ('H1',1,'{"key": "H1", "text": "A small object that means a lot to you, and the story behind it.", "stage": 2, "section": "H"}'::jsonb),
 ('H2',1,'{"key": "H2", "text": "A place you know inside out — one you could describe with your eyes closed.", "stage": 2, "section": "H"}'::jsonb),
 ('H3',1,'{"key": "H3", "text": "A skill or bit of knowledge you have that seems useless but that you''re weirdly good at.", "stage": 2, "section": "H"}'::jsonb),
 ('H4',1,'{"key": "H4", "text": "The last time you completely lost track of time — what were you doing?", "stage": 2, "section": "H"}'::jsonb),
 ('H5',1,'{"key": "H5", "text": "A moment you surprised yourself — said or did something you didn''t know you had in you.", "stage": 2, "section": "H"}'::jsonb),
 ('H6',1,'{"key": "H6", "text": "A specific person who changed you, and one real scene with them you still remember. (Not a summary of the whole relationship — an actual moment.)", "stage": 2, "section": "H"}'::jsonb),
 ('H7',1,'{"key": "H7", "text": "Something funny, strange, or a little embarrassing about you that still says something true about who you are.", "stage": 2, "section": "H"}'::jsonb),
 ('H8',1,'{"key": "H8", "text": "A habit, routine, or way of doing things that''s distinctly yours.", "stage": 2, "section": "H"}'::jsonb),
 ('I1',1,'{"key": "I1", "text": "Why do you want to go to college — beyond it being the expected next step? What do you actually want from it?", "stage": 1, "section": "I"}'::jsonb),
 ('I2',1,'{"key": "I2", "text": "Any careers or directions you''re curious about, even loose or unlikely ones.", "stage": 1, "section": "I"}'::jsonb),
 ('I3',1,'{"key": "I3", "text": "Something you''d like to see change — in your community, a field you care about, or the world — and any sense of how you''d want to help.", "stage": 3, "section": "I"}'::jsonb),
 ('I4',1,'{"key": "I4", "text": "Do you see a thread connecting where you''ve come from to where you want to go? Describe it, even roughly.", "stage": 3, "section": "I"}'::jsonb),
 ('J1',1,'{"key": "J1", "text": "What matters most to you in a college? (Size, location, city vs. small town, academic feel, social scene, specific programs, distance from home…)", "stage": 1, "section": "J"}'::jsonb),
 ('J2',1,'{"key": "J2", "text": "Any hard requirements we should plan around — financial aid needs, staying within a certain distance, a specific program or major, family considerations.", "stage": 1, "section": "J"}'::jsonb),
 ('J3',1,'{"key": "J3", "text": "Do any of these apply to you: recruited athlete, legacy, a standout talent (arts, research, business), a significant unusual circumstance, or another distinguishing factor?", "stage": 1, "section": "J"}'::jsonb),
 ('J4',1,'{"key": "J4", "text": "Where''s your thinking right now on reach / target / safety schools — and how set or open is your list?", "stage": 1, "section": "J"}'::jsonb),
 ('J5',1,'{"key": "J5", "text": "Is there anything you know you don''t want to write about or highlight? (Just as useful for us to know as what you do.)", "stage": 3, "section": "J"}'::jsonb),
 ('J6',1,'{"key": "J6", "text": "Anything important about you that none of these questions managed to reach?", "stage": 3, "section": "J"}'::jsonb),
 ('P1',1,'{"key": "P1", "text": "Choose your three highest college priorities, in order. It is okay to leave some undecided.", "stage": 1, "section": "P"}'::jsonb),
 ('P2',1,'{"key": "P2", "text": "Where could you be flexible? Describe one tradeoff you would consider and one requirement you would not give up.", "stage": 1, "section": "P"}'::jsonb),
 ('P3',1,'{"key": "P3", "text": "What helps you learn, feel included, and ask for support? What would you want available at college?", "stage": 1, "section": "P"}'::jsonb),
 ('P4',1,'{"key": "P4", "text": "What excites or worries you about this process, and how would you like your counselor to help?", "stage": 1, "section": "P"}'::jsonb),
 ('R1',1,'{"key": "R1", "text": "What do you hope your student gains from college, in their own life?", "stage": 1, "section": "R", "format": "text", "version": 2, "options": []}'::jsonb),
 ('R2',1,'{"key": "R2", "text": "What financial, location, family or timing constraints should the counselor plan around? Share only what is useful for planning.", "stage": 1, "section": "R", "format": "text", "version": 2, "options": []}'::jsonb),
 ('R3',1,'{"key": "R3", "text": "Where do your preferences and your student''s preferences differ? Where can you be flexible?", "stage": 1, "section": "R", "format": "text", "version": 2, "options": []}'::jsonb),
 ('R4',1,'{"key": "R4", "text": "Describe a specific moment that shows a strength, interest or quality in your student.", "stage": 2, "section": "R", "format": "text", "version": 2, "options": []}'::jsonb),
 ('R5',1,'{"key": "R5", "text": "What responsibilities, changes or circumstances might help the counselor understand your student''s experience?", "stage": 2, "section": "R", "format": "text", "version": 2, "options": []}'::jsonb),
 ('R6',1,'{"key": "R6", "text": "When does your student seem most engaged, comfortable or proud? What support helps them thrive?", "stage": 2, "section": "R", "format": "text", "version": 2, "options": []}'::jsonb),
 ('R7',1,'{"key": "R7", "text": "How would you like to participate, and what decisions should your student lead?", "stage": 3, "section": "R", "format": "text", "version": 2, "options": []}'::jsonb),
 ('R8',1,'{"key": "R8", "text": "What would you like to discuss privately with the counseling team? Is there anything else they should understand?", "stage": 3, "section": "R", "format": "text", "version": 2, "options": []}'::jsonb),
 ('A1',2,'{"key": "A1", "text": "Does this look right for you?", "stage": 1, "section": "A", "version": 2, "format": "confirm", "options": [{"id": "confirm", "label": "Yes, this is right"}, {"id": "correction", "label": "I have an update"}], "source": {"document": "Getting to Know You questionnaire", "key": "A1"}, "help": "Choose what fits today. It is okay for this to change."}'::jsonb),
 ('A2',2,'{"key": "A2", "text": "Is this still your school?", "stage": 1, "section": "A", "version": 2, "format": "confirm", "options": [{"id": "confirm", "label": "Yes, this is right"}, {"id": "correction", "label": "I have an update"}], "source": {"document": "Getting to Know You questionnaire", "key": "A2"}, "help": "Choose what fits today. It is okay for this to change."}'::jsonb),
 ('A3',2,'{"key": "A3", "text": "How are you feeling about what you might study?", "stage": 1, "section": "A", "version": 2, "format": "single", "options": [{"id": "focused", "label": "I have a field in mind"}, {"id": "exploring", "label": "I want to try several fields"}, {"id": "undecided", "label": "Still figuring it out"}], "source": {"document": "Getting to Know You questionnaire", "key": "A3"}, "help": "Choose what fits today. It is okay for this to change.", "criterion": "program"}'::jsonb),
 ('A4',2,'{"key": "A4", "text": "Is there a college you are curious about? What caught your attention?", "stage": 1, "section": "A", "version": 2, "format": "text", "options": [], "source": {"document": "Getting to Know You questionnaire", "key": "A4"}, "help": "A few words or bullet points are enough. You can return later."}'::jsonb),
 ('I1',2,'{"key": "I1", "text": "What would you like college to make room for in your life?", "stage": 1, "section": "I", "version": 2, "format": "multi", "options": [{"id": "learning", "label": "Learning about subjects I enjoy"}, {"id": "career", "label": "Preparing for work I care about"}, {"id": "independence", "label": "Trying more things on my own"}, {"id": "people", "label": "Meeting people and building community"}, {"id": "impact", "label": "Contributing to something I care about"}, {"id": "other", "label": "Something else"}, {"id": "undecided", "label": "Still figuring it out"}], "source": {"document": "Getting to Know You questionnaire", "key": "I1"}, "help": "Choose what fits today. It is okay for this to change."}'::jsonb),
 ('I2',2,'{"key": "I2", "text": "Any work or future directions you are curious about? A rough idea is enough.", "stage": 1, "section": "I", "version": 2, "format": "text", "options": [], "source": {"document": "Getting to Know You questionnaire", "key": "I2"}, "help": "A few words or bullet points are enough. You can return later."}'::jsonb),
 ('P1',2,'{"key": "P1", "text": "If we start with three things, what should they be? Put the most important first.", "stage": 1, "section": "I", "version": 2, "format": "rank", "options": [{"id": "academics", "label": "Academic programs"}, {"id": "exploration", "label": "Freedom to explore"}, {"id": "cost", "label": "Cost and financial aid"}, {"id": "distance", "label": "Distance from home"}, {"id": "size", "label": "Campus size"}, {"id": "setting", "label": "Location and setting"}, {"id": "community", "label": "Community and belonging"}, {"id": "support", "label": "Learning and support"}, {"id": "career", "label": "Career opportunities"}], "source": {"document": "Getting to Know You questionnaire", "key": "P1"}, "help": "Choose what fits today. It is okay for this to change."}'::jsonb),
 ('J1',2,'{"key": "J1", "text": "When you picture feeling at home at college, what comes to mind?", "stage": 1, "section": "I", "version": 2, "format": "text", "options": [], "source": {"document": "Getting to Know You questionnaire", "key": "J1"}, "help": "A few words or bullet points are enough. You can return later."}'::jsonb),
 ('FIT_SIZE',2,'{"key": "FIT_SIZE", "text": "How many people would you like around you on campus?", "stage": 1, "section": "FIT", "version": 2, "format": "multi", "options": [{"id": "small", "label": "Under 5,000 undergraduates"}, {"id": "medium", "label": "5,000 to 15,000 undergraduates"}, {"id": "large", "label": "More than 15,000 undergraduates"}, {"id": "flexible", "label": "No strong preference"}, {"id": "undecided", "label": "Still figuring it out"}], "source": {"document": "CounselWorks conversational interview v2", "key": "FIT_SIZE"}, "criterion": "size", "help": "Tell us what you prefer, then say how much it matters. We will check the details together."}'::jsonb),
 ('FIT_SETTING',2,'{"key": "FIT_SETTING", "text": "What would you like to find just outside campus?", "stage": 1, "section": "FIT", "version": 2, "format": "multi", "options": [{"id": "city", "label": "A city with lots going on"}, {"id": "suburb", "label": "A suburban area near a city"}, {"id": "town", "label": "A town built around local life"}, {"id": "rural", "label": "A quieter rural setting"}, {"id": "flexible", "label": "No strong preference"}, {"id": "undecided", "label": "Still figuring it out"}], "source": {"document": "CounselWorks conversational interview v2", "key": "FIT_SETTING"}, "criterion": "setting", "help": "Tell us what you prefer, then say how much it matters. We will check the details together."}'::jsonb),
 ('FIT_DISTANCE',2,'{"key": "FIT_DISTANCE", "text": "How are you thinking about getting home from college?", "stage": 1, "section": "FIT", "version": 2, "format": "single", "options": [{"id": "near", "label": "I want to be able to get home easily"}, {"id": "travel", "label": "I am comfortable planning a longer trip"}, {"id": "anywhere", "label": "I am open to being far from home"}, {"id": "depends", "label": "It depends on cost or family needs"}, {"id": "undecided", "label": "Still figuring it out"}], "source": {"document": "CounselWorks conversational interview v2", "key": "FIT_DISTANCE"}, "criterion": "distance", "help": "Tell us what you prefer, then say how much it matters. We will check the details together."}'::jsonb),
 ('FIT_STATES',2,'{"key": "FIT_STATES", "text": "Which states would work for you? Choose any you want us to consider.", "stage": 1, "section": "FIT", "version": 2, "format": "multi", "options": [{"id": "AL", "label": "AL"}, {"id": "AK", "label": "AK"}, {"id": "AZ", "label": "AZ"}, {"id": "AR", "label": "AR"}, {"id": "CA", "label": "CA"}, {"id": "CO", "label": "CO"}, {"id": "CT", "label": "CT"}, {"id": "DE", "label": "DE"}, {"id": "DC", "label": "DC"}, {"id": "FL", "label": "FL"}, {"id": "GA", "label": "GA"}, {"id": "HI", "label": "HI"}, {"id": "ID", "label": "ID"}, {"id": "IL", "label": "IL"}, {"id": "IN", "label": "IN"}, {"id": "IA", "label": "IA"}, {"id": "KS", "label": "KS"}, {"id": "KY", "label": "KY"}, {"id": "LA", "label": "LA"}, {"id": "ME", "label": "ME"}, {"id": "MD", "label": "MD"}, {"id": "MA", "label": "MA"}, {"id": "MI", "label": "MI"}, {"id": "MN", "label": "MN"}, {"id": "MS", "label": "MS"}, {"id": "MO", "label": "MO"}, {"id": "MT", "label": "MT"}, {"id": "NE", "label": "NE"}, {"id": "NV", "label": "NV"}, {"id": "NH", "label": "NH"}, {"id": "NJ", "label": "NJ"}, {"id": "NM", "label": "NM"}, {"id": "NY", "label": "NY"}, {"id": "NC", "label": "NC"}, {"id": "ND", "label": "ND"}, {"id": "OH", "label": "OH"}, {"id": "OK", "label": "OK"}, {"id": "OR", "label": "OR"}, {"id": "PA", "label": "PA"}, {"id": "RI", "label": "RI"}, {"id": "SC", "label": "SC"}, {"id": "SD", "label": "SD"}, {"id": "TN", "label": "TN"}, {"id": "TX", "label": "TX"}, {"id": "UT", "label": "UT"}, {"id": "VT", "label": "VT"}, {"id": "VA", "label": "VA"}, {"id": "WA", "label": "WA"}, {"id": "WV", "label": "WV"}, {"id": "WI", "label": "WI"}, {"id": "WY", "label": "WY"}, {"id": "flexible", "label": "Any state could work"}, {"id": "undecided", "label": "Still figuring it out"}], "source": {"document": "CounselWorks conversational interview v2", "key": "FIT_STATES"}, "criterion": "states", "help": "Tell us what you prefer, then say how much it matters. We will check the details together."}'::jsonb),
 ('FIT_TYPE',2,'{"key": "FIT_TYPE", "text": "Do you have a preference for public or private colleges?", "stage": 1, "section": "FIT", "version": 2, "format": "multi", "options": [{"id": "public", "label": "Public"}, {"id": "private", "label": "Private nonprofit"}, {"id": "flexible", "label": "Either could work"}, {"id": "undecided", "label": "Still figuring it out"}], "source": {"document": "CounselWorks conversational interview v2", "key": "FIT_TYPE"}, "criterion": "type", "help": "Tell us what you prefer, then say how much it matters. We will check the details together."}'::jsonb),
 ('FIT_FRIDAY',2,'{"key": "FIT_FRIDAY", "text": "It is Friday evening and you have some time to yourself. What could sound good?", "stage": 1, "section": "LIFE", "version": 2, "format": "multi", "options": [{"id": "event", "label": "Joining a campus event"}, {"id": "friends", "label": "Hanging out with a few friends"}, {"id": "town", "label": "Exploring the area"}, {"id": "hobby", "label": "Spending time on a hobby"}, {"id": "alone", "label": "Taking some quiet time"}, {"id": "depends", "label": "It depends on the week"}], "source": {"document": "CounselWorks conversational interview v2", "key": "FIT_FRIDAY"}, "criterion": "social", "help": "Tell us what you prefer, then say how much it matters. We will check the details together."}'::jsonb),
 ('FIT_COMMUNITY',2,'{"key": "FIT_COMMUNITY", "text": "What would help you feel that you belong?", "stage": 1, "section": "LIFE", "version": 2, "format": "multi", "options": [{"id": "small", "label": "A smaller group I see regularly"}, {"id": "variety", "label": "Meeting people with different experiences"}, {"id": "identity", "label": "A community connected to my identity or interests"}, {"id": "activity", "label": "Doing an activity together"}, {"id": "other", "label": "Something else"}, {"id": "undecided", "label": "Still figuring it out"}], "source": {"document": "CounselWorks conversational interview v2", "key": "FIT_COMMUNITY"}, "criterion": "community", "help": "Tell us what you prefer, then say how much it matters. We will check the details together."}'::jsonb),
 ('FIT_LEARNING',2,'{"key": "FIT_LEARNING", "text": "A class is tackling a new idea. What would help you get into it?", "stage": 1, "section": "LIFE", "version": 2, "format": "multi", "options": [{"id": "discussion", "label": "Talking in a smaller group"}, {"id": "lecture", "label": "Hearing a clear explanation"}, {"id": "practice", "label": "Trying a project or experiment"}, {"id": "independent", "label": "Working it through at my own pace"}, {"id": "depends", "label": "It depends on the class"}], "source": {"document": "CounselWorks conversational interview v2", "key": "FIT_LEARNING"}, "criterion": "learning", "help": "Tell us what you prefer, then say how much it matters. We will check the details together."}'::jsonb),
 ('FIT_ACTIVITIES',2,'{"key": "FIT_ACTIVITIES", "text": "What would you like room for outside class?", "stage": 1, "section": "LIFE", "version": 2, "format": "multi", "options": [{"id": "arts", "label": "Arts or making things"}, {"id": "sport", "label": "Sports or movement"}, {"id": "service", "label": "Community involvement"}, {"id": "research", "label": "Research or projects"}, {"id": "work", "label": "Paid work"}, {"id": "quiet", "label": "Unstructured time"}, {"id": "other", "label": "Something else"}, {"id": "undecided", "label": "Still figuring it out"}], "source": {"document": "CounselWorks conversational interview v2", "key": "FIT_ACTIVITIES"}, "criterion": "activities", "help": "Tell us what you prefer, then say how much it matters. We will check the details together."}'::jsonb),
 ('P3',2,'{"key": "P3", "text": "What helps when learning gets difficult or life gets busy?", "stage": 1, "section": "PLAN", "version": 2, "format": "multi", "options": [{"id": "advising", "label": "Someone I can check in with"}, {"id": "tutoring", "label": "Academic help when I need it"}, {"id": "access", "label": "Access accommodations"}, {"id": "wellbeing", "label": "Wellbeing or mental health support"}, {"id": "community", "label": "A familiar community or peer group"}, {"id": "other", "label": "Something else"}, {"id": "undecided", "label": "Still figuring it out"}], "source": {"document": "Getting to Know You questionnaire", "key": "P3"}, "help": "Choose what fits today. It is okay for this to change.", "criterion": "support"}'::jsonb),
