-- Additive interview redesign. No answer/audience backfill and no profile writes.
-- Created with the CLI, numbered to follow the repository's sequential convention.
CREATE TABLE public.interview_question_definitions (
 question_key text NOT NULL, version integer NOT NULL CHECK(version IN (1,2)),
 definition jsonb NOT NULL CHECK(jsonb_typeof(definition)='object'),
 PRIMARY KEY(question_key,version)
);
ALTER TABLE public.interview_question_definitions ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.interview_question_definitions FROM PUBLIC,anon,authenticated;
GRANT SELECT ON public.interview_question_definitions TO authenticated;
GRANT ALL ON public.interview_question_definitions TO service_role;
CREATE POLICY interview_definitions_read ON public.interview_question_definitions FOR SELECT TO authenticated USING(true);
-- Immutable released definitions; wording/meaning changes require a new version.
ALTER TABLE public.student_interview_answers
 DROP CONSTRAINT student_interview_answers_template_version_check,
 DROP CONSTRAINT student_interview_answers_question_key_check,
 DROP CONSTRAINT student_interview_answers_state_check,
 ADD CONSTRAINT interview_template_version CHECK(template_version IN (1,2)),
 ADD CONSTRAINT interview_definition FOREIGN KEY(question_key,template_version) REFERENCES public.interview_question_definitions(question_key,version),
 ADD COLUMN structured_response jsonb,
 ADD COLUMN discussion_requested boolean NOT NULL DEFAULT false,
 ADD CONSTRAINT interview_response_format CHECK (
  (template_version=1 AND structured_response IS NULL AND state IN ('answered','unsure','skip','discuss') AND NOT discussion_requested)
  OR (template_version=2 AND structured_response IS NOT NULL AND state IN ('answered','unsure','deferred','declined'))
 );
ALTER TABLE public.student_interview_followups ADD COLUMN discussion_request boolean NOT NULL DEFAULT false;
CREATE UNIQUE INDEX interview_one_discussion_followup ON public.student_interview_followups(source_answer_id) WHERE discussion_request;

CREATE OR REPLACE FUNCTION public.guard_interview_answer() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$
DECLARE r text; d jsonb; ids jsonb; note text; importance text; rendered text; n integer;
BEGIN
 IF current_user NOT IN ('postgres','service_role') THEN
  r:=public.work_actor(NEW.firm_id,public.current_user_id(),NEW.student_id);
  IF NEW.respondent_user_id IS DISTINCT FROM public.current_user_id()
   OR (NEW.respondent_kind='student' AND r<>'student') OR (NEW.respondent_kind='parent' AND r<>'parent_guardian')
  THEN RAISE EXCEPTION 'Only the respondent can change an interview response'; END IF;
  IF TG_OP='UPDATE' THEN
   IF (NEW.id,NEW.firm_id,NEW.student_id,NEW.respondent_user_id,NEW.respondent_kind,NEW.question_key)
    IS DISTINCT FROM (OLD.id,OLD.firm_id,OLD.student_id,OLD.respondent_user_id,OLD.respondent_kind,OLD.question_key)
    OR (NEW.template_version<>OLD.template_version AND NOT (OLD.template_version=1 AND NEW.template_version=2))
   THEN RAISE EXCEPTION 'Response identity cannot change'; END IF;
   IF NEW.revision<>OLD.revision+1 THEN RAISE EXCEPTION 'Response changed; reload before saving'; END IF;
  ELSIF NEW.revision<>1 THEN RAISE EXCEPTION 'Invalid initial revision'; END IF;
 END IF;
 IF (NEW.respondent_kind='parent') IS DISTINCT FROM (NEW.question_key ~ '^R[1-8]$') THEN RAISE EXCEPTION 'Unknown interview question'; END IF;
 -- Explicit consent can override this default. Old rows are never updated here.
 IF TG_OP='INSERT' AND NEW.audience IS NULL THEN NEW.audience:=CASE WHEN NEW.respondent_kind='student' AND NEW.template_version=2 THEN 'family' ELSE 'counselor' END; END IF;
 IF NEW.template_version=2 THEN
  SELECT definition INTO d FROM public.interview_question_definitions WHERE question_key=NEW.question_key AND version=2;
  IF d IS NULL THEN RAISE EXCEPTION 'Unknown interview question'; END IF;
  IF jsonb_typeof(NEW.structured_response) IS DISTINCT FROM 'object'
   OR NEW.structured_response->'version' IS DISTINCT FROM '2'::jsonb
   OR jsonb_typeof(NEW.structured_response->'optionIds') IS DISTINCT FROM 'array'
   OR jsonb_typeof(NEW.structured_response->'text') IS DISTINCT FROM 'string'
   OR NEW.structured_response->>'importance' IS NULL
   OR NEW.structured_response->>'importance' NOT IN ('preference','important','requirement')
   OR NOT (NEW.structured_response ? 'importance')
   OR (SELECT count(*) FROM jsonb_object_keys(NEW.structured_response))<>4
  THEN RAISE EXCEPTION 'Invalid structured response'; END IF;
  ids:=NEW.structured_response->'optionIds';note:=btrim(NEW.structured_response->>'text');importance:=NEW.structured_response->>'importance';n:=jsonb_array_length(ids);
  IF length(note)>6000 OR n>54 OR n<>(SELECT count(DISTINCT x) FROM jsonb_array_elements(ids) x)
   OR EXISTS(SELECT 1 FROM jsonb_array_elements(ids) x WHERE jsonb_typeof(x)<>'string' OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(d->'options','[]')) o WHERE o->'id'=x))
   OR (d->>'format' IN ('single','confirm') AND n>1) OR (d->>'format'='rank' AND n>3) OR (d->>'format'='text' AND n>0)
   OR (n>1 AND (ids ? 'flexible' OR ids ? 'undecided'))
   OR (NEW.state='answered' AND (ids ? 'undecided' OR (n=0 AND (note='' OR d->>'format'<>'text'))))
   OR (NEW.state='answered' AND d->>'format'='confirm' AND ids ? 'correction' AND note='')
  THEN RAISE EXCEPTION 'Invalid structured choices'; END IF;
  SELECT string_agg(CASE WHEN d->>'format'='rank' THEN i.ordinality::text||'. ' ELSE '' END||(SELECT o->>'label' FROM jsonb_array_elements(coalesce(d->'options','[]')) o WHERE o->'id'=i.value),E'\n' ORDER BY i.ordinality)
   INTO rendered FROM jsonb_array_elements(ids) WITH ORDINALITY i(value,ordinality);
  NEW.answer:=concat_ws(E'\n',nullif(rendered,''),nullif(note,''),CASE WHEN d ? 'criterion' AND (n>0 OR note<>'') THEN CASE importance WHEN 'requirement' THEN 'A requirement — please check this' WHEN 'important' THEN 'Important — worth weighing carefully' ELSE 'A preference — I can be flexible' END END);
 END IF;
 NEW.updated_at:=now();RETURN NEW;
END $$;

-- Keep the existing follow-up ownership/revision guard, with an independent
-- validation trigger for the deduplicated discussion workflow.
CREATE FUNCTION public.guard_interview_discussion() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$
BEGIN
 IF TG_OP='UPDATE' AND NEW.discussion_request<>OLD.discussion_request THEN RAISE EXCEPTION 'Follow-up identity cannot change'; END IF;
 IF TG_OP='INSERT' AND NEW.discussion_request AND NOT EXISTS(
  SELECT 1 FROM public.student_interview_answers a WHERE a.id=NEW.source_answer_id AND a.firm_id=NEW.firm_id
   AND a.student_id=NEW.student_id AND a.respondent_user_id=NEW.recipient_user_id AND a.discussion_requested)
 THEN RAISE EXCEPTION 'Choose a current discussion request'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER guard_interview_discussion BEFORE INSERT OR UPDATE ON public.student_interview_followups FOR EACH ROW EXECUTE FUNCTION public.guard_interview_discussion();
REVOKE ALL ON FUNCTION public.guard_interview_discussion() FROM PUBLIC,anon,authenticated;

-- Deferred/declined responses are excluded from AI context just like legacy
-- skip/discuss. A new discussion_requested flag NEVER excludes an answer.
CREATE FUNCTION public.interview_answer_active(p_firm uuid,p_student uuid,p_respondent uuid,p_key text,p_version integer)
RETURNS boolean LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$
 SELECT p_version=1 OR NOT (d.definition ? 'branch') OR EXISTS (
  SELECT 1 FROM public.student_interview_answers a WHERE a.firm_id=p_firm AND a.student_id=p_student AND a.respondent_user_id=p_respondent
   AND a.question_key=d.definition->'branch'->>'question' AND a.state IN ('answered','unsure')
   AND EXISTS(SELECT 1 FROM jsonb_array_elements_text(d.definition->'branch'->'options') o WHERE a.structured_response->'optionIds' ? o)
 ) FROM public.interview_question_definitions d WHERE d.question_key=p_key AND d.version=p_version
$$;
REVOKE ALL ON FUNCTION public.interview_answer_active(uuid,uuid,uuid,text,integer) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.interview_answer_active(uuid,uuid,uuid,text,integer) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.student_ai_context(p_firm uuid,p_actor uuid,p_student uuid,p_recipient uuid)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path=public AS $$
DECLARE r text; target text; sources jsonb; excluded jsonb;
BEGIN
 r:=public.work_actor(p_firm,p_actor,p_student);
 IF r NOT IN ('firm_owner','firm_admin','counselor','essay_coach','tutor','student','parent_guardian')
  OR (r IN ('student','parent_guardian') AND p_actor IS DISTINCT FROM p_recipient)
 THEN RAISE EXCEPTION 'AI interview access required'; END IF;
 SELECT CASE WHEN s.user_id=p_recipient AND m.role='student' THEN 'student' ELSE 'parent' END INTO target
 FROM students s JOIN firm_memberships m ON m.firm_id=s.firm_id AND m.user_id=p_recipient AND m.status='active'
 WHERE s.id=p_student AND s.firm_id=p_firm AND ((s.user_id=p_recipient AND m.role='student') OR (m.role='parent_guardian' AND EXISTS(
  SELECT 1 FROM family_members f WHERE f.firm_id=p_firm AND f.family_id=s.family_id AND f.user_id=p_recipient)));
 IF target IS NULL THEN RAISE EXCEPTION 'Choose an active interview respondent'; END IF;
 SELECT coalesce(jsonb_agg(x.source ORDER BY x.sort,x.id),'[]') INTO sources FROM (
  SELECT 1 sort,a.id,jsonb_build_object('kind','answer','id',a.id,'revision',a.revision,'stamp',md5(to_jsonb(a)::text),
   'label',a.question_key,'questionKey',a.question_key,'entryKind',NULL,'text',a.answer) source
  FROM student_interview_answers a WHERE a.firm_id=p_firm AND a.student_id=p_student AND a.respondent_user_id=p_recipient
   AND a.respondent_kind=target AND public.interview_answer_active(a.firm_id,a.student_id,a.respondent_user_id,a.question_key,a.template_version) AND a.state IN ('answered','unsure') AND length(btrim(a.answer))>0
  UNION ALL
  SELECT 2,b.id,jsonb_build_object('kind','bank','id',b.id,'revision',b.revision,
   'stamp',md5((to_jsonb(b)||jsonb_build_object('support',coalesce((SELECT jsonb_agg(jsonb_build_object('id',s.id,'revision',s.revision,'audience',s.audience,'review',s.review_state) ORDER BY s.id) FROM student_story_bank s WHERE s.firm_id=p_firm AND s.student_id=p_student AND s.id=ANY(b.story_ids)),'[]')))::text),
   'label',b.title,'questionKey',NULL,'entryKind',b.kind,'text',b.body||CASE WHEN b.reflection<>'' THEN E'\nReflection: '||b.reflection ELSE '' END)
  FROM student_story_bank b WHERE b.firm_id=p_firm AND b.student_id=p_student AND b.review_state='confirmed'
   AND (target='student' OR b.audience='family')
   AND (b.kind='story' OR (cardinality(b.story_ids)>0 AND cardinality(b.story_ids)=(SELECT count(*) FROM student_story_bank s WHERE s.firm_id=p_firm AND s.student_id=p_student AND s.id=ANY(b.story_ids) AND s.kind='story' AND s.review_state='confirmed' AND (target='student' OR s.audience='family'))))
  UNION ALL
  SELECT 3,s.id,jsonb_build_object('kind','strategy','id',s.id,'revision',s.revision,'stamp',md5(to_jsonb(s)::text),
   'label',s.section_key,'questionKey',NULL,'entryKind',NULL,'text',s.body||CASE WHEN s.student_note<>'' THEN E'\nStudent review note: '||s.student_note ELSE '' END)
  FROM student_strategy_sections s WHERE s.firm_id=p_firm AND s.student_id=p_student AND s.section_key<>'counselor_notes'
   AND s.publication_state='shared' AND s.student_review='accurate' AND (target='student' OR s.family_shared)
   AND public.strategy_sources_ready(p_firm,p_student,s.evidence,CASE WHEN target='student' THEN 'student' ELSE 'family' END,true)
  UNION ALL
  SELECT 4,f.id,jsonb_build_object('kind','followup','id',f.id,'revision',f.revision,'stamp',md5(to_jsonb(f)::text),
   'label',f.question,'questionKey',NULL,'entryKind',NULL,'text','Question: '||f.question||E'\nRespondent reply: '||f.reply)
  FROM student_interview_followups f WHERE f.firm_id=p_firm AND f.student_id=p_student AND f.recipient_user_id=p_recipient AND length(btrim(f.reply))>0
 ) x;
 SELECT coalesce(jsonb_agg(question_key ORDER BY question_key),'[]') INTO excluded FROM student_interview_answers
 WHERE firm_id=p_firm AND student_id=p_student AND respondent_user_id=p_recipient AND (state IN ('skip','discuss','deferred','declined') OR NOT public.interview_answer_active(firm_id,student_id,respondent_user_id,question_key,template_version));
 RETURN jsonb_build_object('recipientKind',target,'sources',sources,'excludedQuestionKeys',excluded);
END $$;
